"""Summoner subclasses, first seven (Summoner 2024). Own wording."""
SUB = {
"Bond of the Guardian Angel": {"spab": "CHA",
 "f": {
  "Celestial Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: Cure Wounds, Sanctuary. Level 5: Lesser Restoration, Prayer of Healing. Level 9: Mass Healing Word, Revivify, Summon Celestial. Level 13: Death Ward, Guardian of Faith. Level 17: Greater Restoration.",
  "Celestial Eidolon": "Your Eidolon looks like an angel or another celestial. **Changes.** Its type is Celestial. Strength 14 (+2), Dexterity 13 (+1), Constitution 16 (+3). It is proficient in Insight and Medicine and resists Necrotic and Radiant damage. **Healing Surge.** When it uses Conjured Strike, it can give up one attack to heal a creature within that attack's range for 2d8 plus your Summoner level. Uses equal your Charisma modifier (minimum 1). A Short Rest restores one use and a Long Rest restores all.",
  "Exalted Presence": "You gain proficiency in Intimidation or Persuasion, your choice. If you already have it, you gain Expertise instead. You also have Advantage on Wisdom (Insight) checks to tell whether a creature is lying.",
  "Mortal Sacrifice": "When you see a creature within 30 feet get hit by an attack while your Eidolon is manifested, you can use your Reaction to teleport the Eidolon to an unoccupied space within 5 feet of that creature. The Eidolon takes the hit instead and has Resistance to its damage. Uses equal your Charisma modifier (minimum 1). A Long Rest restores all.",
  "Prodigious Healer": "When your Eidolon heals with Healing Surge, it can also end one of these conditions on the target: Blinded, Charmed, Deafened, Frightened, Paralyzed, Poisoned, or Stunned. If it ends none, it adds your Charisma modifier (minimum +1) to the healing roll.",
  "Immortal Bulwark": "At the start of each of your turns, your Eidolon gains Temporary Hit Points equal to half your Summoner level. Mortal Sacrifice no longer has a limit on uses."},
 "lu": [{"feature": "Celestial Eidolon", "n": "Healing Surge", "lvl": 3, "max": "mod:CHA", "reset": "long", "tag": "Short Rest restores 1"},
        {"feature": "Mortal Sacrifice", "lvl": 6, "max": "mod:CHA", "reset": "long", "tag": "Reaction"}],
 "acts": {"Mortal Sacrifice": "reaction"},
 "fx": [[3, "Exalted Presence", {"notes": [["Note", "Exalted Presence: proficiency (or Expertise) in Intimidation or Persuasion, Advantage on Insight checks to detect lies"]]}],
        [3, "Celestial Eidolon", {"notes": [["Note", "Eidolon resists Necrotic and Radiant damage"]]}]]},

"Bond of the Dragon Herald": {"spab": "CHA",
 "f": {
  "Draconic Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: Burning Hands, Disguise Self. Level 5: Dragon's Breath, Shatter. Level 9: Fireball, Protection from Energy, Summon Dragon. Level 13: Charm Monster, Stoneskin. Level 17: Cone of Cold.",
  "Dragon Eidolon": "Your Eidolon is a wingless, four-legged Medium dragon. **Changes.** Its type is Dragon. Strength 16 (+3), Dexterity 13 (+1), Constitution 14 (+2). It is proficient in Perception and Persuasion. **Draconic Type.** Pick a type when you choose this subclass. The Eidolon resists that damage. Amethyst is Force. Black or Copper is Acid. Blue or Bronze is Lightning. Crystal is Radiant. Emerald is Psychic. Green is Poison. Red, Gold, or Brass is Fire. Sapphire is Thunder. Topaz is Necrotic. White or Silver is Cold. **Breath Weapon (cost 1+ AP).** Each creature in a 15-foot Cone or a 30-foot long, 5-foot wide Line makes a Dexterity save against your spell save DC. On a failure it takes 2d6 damage of the Draconic Type, plus 1d6 per AP spent beyond the first. On a success it takes half. The base damage becomes 3d6 at level 6 and 4d6 at level 14. Uses equal your Charisma modifier (minimum 1). A Short Rest restores one use and a Long Rest restores all. **Elemental Bond.** While the Eidolon is manifested, you can change the damage type of your Summoner damage spells to its Draconic Type.",
  "Evocation Expert": "Conjuration Expert also covers Evocation spells. Wizard Evocation spells are added to your Summoner spell list.",
  "Summoner's Blast": "**Empowered Blast.** When you cast a level 1+ Summoner spell that deals damage, you can add your Charisma modifier (minimum +1) to one of its damage rolls. **Free Casting.** After each Long Rest, pick one Summoner Evocation spell of a level up to half your Summoner level (round up, maximum 5). Evocation spells from Draconic Spells are valid. Once before your next Long Rest you can cast it without a spell slot.",
  "Empowered Breath Weapon": "When you cast a level 1+ spell that deals damage of the Eidolon's Draconic Type, its Breath Weapon is empowered until the end of your turn. The area becomes a 30-foot Cone or a 60-foot Line, and it adds your Charisma modifier (minimum +1) to the damage.",
  "Draconic Realisation": "Your Eidolon is Immune to the Frightened condition and has a Fly Speed of 60 feet. It becomes Immune to its Draconic Type damage, and its Conjured Strike deals an extra 1d6 of that type on a hit."},
 "lu": [{"feature": "Dragon Eidolon", "n": "Breath Weapon", "lvl": 3, "max": "mod:CHA", "reset": "long", "tag": "Short Rest restores 1"},
        {"feature": "Summoner's Blast", "n": "Free Casting", "lvl": 6, "max": 1, "reset": "long", "tag": "Evocation spell"}],
 "acts": {},
 "fx": [[3, "Dragon Eidolon", {"notes": [["Note", "Eidolon resists the damage of its Draconic Type and breathes it (Breath Weapon)"]]}]]},

"Bond of the Faerie Trickster": {"spab": "CHA",
 "f": {
  "Fey Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: Charm Person, Faerie Fire. Level 5: Calm Emotions, Phantasmal Force, Summon Fey. Level 9: Hypnotic Pattern. Level 13: Greater Invisibility, Polymorph. Level 17: Dominate Person, Geas.",
  "Faerie Eidolon": "Your Eidolon is a pixie, sprite, or similar winged creature about 3 to 8 inches tall. **Changes.** Its type is Fey and its size is Tiny. Strength 8 (-1), Dexterity 16 (+3), Constitution 14 (+2). It is proficient in Deception and Stealth. It has a Fly Speed equal to its Speed. **Invisibility (cost 1 AP).** It becomes Invisible until it attacks, forces a save, or becomes Incapacitated. It can end the effect at will with no action.",
  "Enchantment Expert": "Conjuration Expert also covers Enchantment spells. Wizard Enchantment spells are added to your Summoner spell list.",
  "Faerie Dust": "Your Eidolon gains the action Faerie Dust (cost 1 AP). It sprinkles dust on a creature within 5 feet. A target friendly to you gains a Fly Speed equal to its Speed and can hover. Any other target uses the Faerie Dust table. The effect lasts 1 minute and ends early if the Eidolon dissipates or uses this action again. All saves use your spell save DC. Roll 1: Wisdom save or the Sleep spell takes effect. 2: Wisdom save or the Tasha's Hideous Laughter spell takes effect. 3: Constitution save or the Reduce effect of Enlarge/Reduce takes effect, with a repeat save at the end of each of its turns. 4: Wisdom save or the Levitate spell takes effect, with a repeat save at the end of each of its turns. 5: Wisdom save or the Charm Monster spell takes effect as if you cast it. 6: Wisdom save or the Confusion spell takes effect. Uses equal your Charisma modifier (minimum 1). A Long Rest restores all.",
  "Fey Suggestion": "While a creature is Charmed by you, you can use a Magic action to suggest a course of action if you or your Eidolon is within 5 feet of it. On its next turn the target follows the command exactly. It can use its action and Bonus Action even if the charm left it Incapacitated. At the end of that turn the Charmed condition ends on it and it is immune to this effect for 24 hours.",
  "Ultimate Trickster": "**Spreading Dust.** Faerie Dust range becomes 30 feet. The Eidolon can spend extra AP to hit one more creature per point, and each target gets the same table result. **Improved Invisibility.** The Eidolon's Invisibility no longer ends when it attacks or forces a save, as long as the attack misses or the target succeeds on the save."},
 "lu": [{"feature": "Faerie Dust", "lvl": 6, "max": "mod:CHA", "reset": "long", "tag": "1 AP"}],
 "acts": {"Fey Suggestion": "action"}},

"Bond of the Elemental Spirit": {"spab": "CHA",
 "f": {
  "Elemental Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: Chromatic Orb, Elementalism, Thunderwave. Level 5: Gust of Wind, Scorching Ray. Level 7: Summon Elemental. Level 9: Water Breathing, Wind Wall. Level 13: Wall of Fire. Level 17: Conjure Elemental, Wall of Stone.",
  "Elemental Eidolon": "Each time you manifest your Eidolon, it appears as an Air, Earth, Fire, or Water elemental of your choice. **Changes.** Its type is Elemental. Strength 14 (+2), Dexterity 13 (+1), Constitution 16 (+3). It can squeeze through a gap as small as one square inch. **Elemental Type.** It resists the listed damage and its Conjured Strike can deal it. Air is Thunder: Fly Speed equal to its Speed, but it cannot fly while Grappling or while mounted. Earth is Bludgeoning: +2 to AC. Fire is Fire: a creature hit by its Conjured Strike begins Burning, and the Eidolon dissipates at once if submerged in water. Water is Cold: Swim Speed equal to its Speed and it can breathe underwater.",
  "Primordial Attunement": "You know Primordial and its dialects Aquan, Auran, Ignan, and Terran. If you cast Elementalism while your Eidolon is manifested, the area you can beckon or sculpt is tripled in every dimension and is tied to the Eidolon's current Elemental Type.",
  "Swap Elements": "As a Bonus Action, you change your Eidolon's Elemental Type to another. It gains 1 AP and an effect based on the new type, using your spell save DC. Air: each creature within 5 feet makes a Strength save or is pushed 10 feet away. Earth: the ground within 10 feet becomes Difficult Terrain. Fire: each creature within 5 feet makes a Dexterity save or takes 2d6 Fire damage, half on a success. This becomes 3d6 at level 10 and 4d6 at level 14. Water: each creature within 5 feet makes a Strength save or has the Prone condition. Uses equal your Charisma modifier (minimum 1). A Long Rest restores all.",
  "Elemental Remodement": "The Eidolon's damage Resistance from its type becomes Immunity, and its type improves. Air: Fly Speed 60 feet, and it can Grapple and be mounted while flying. Earth: Resistance to Piercing and Slashing damage. Fire: the Burning hazard it causes deals 1d10. Water: when it hits with Conjured Strike, it can use its Bonus Action for an Unarmed Strike against the target, choosing Grapple or Shove, using your spell save DC.",
  "Twin Eidolons": "When you manifest your Eidolon, you can conjure two at once. If one is already out, you manifest a second. They cannot share an Elemental Type. Your action or Bonus Action sacrifice gives AP to both. With Swap Elements, you choose whether one or both change type. Only one carries your Eidolon's attuned magic items. Your magic sustains both for 10 minutes, then one of your choice dissipates. You cannot use this again until you finish a Short or Long Rest, or you can restore it by expending a level 4+ spell slot (no action)."},
 "lu": [{"feature": "Swap Elements", "lvl": 6, "max": "mod:CHA", "reset": "long", "tag": "Bonus Action"},
        {"feature": "Twin Eidolons", "lvl": 14, "max": 1, "reset": "short", "tag": "10 minutes"}],
 "acts": {"Swap Elements": "bonus"},
 "grant": {"f": "Primordial Attunement"},
 "fx": [[3, "Primordial Attunement", {"langs": ["Primordial", "Aquan", "Auran", "Ignan", "Terran"]}]]},

"Bond of the Fiendish Chain": {"spab": "CHA",
 "f": {
  "Fiend Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: Command, Hellish Rebuke. Level 5: Darkness, Scorching Ray. Level 9: Fear, Fireball. Level 11: Summon Fiend. Level 13: Fire Shield, Wall of Fire. Level 17: Dominate Person.",
  "Fiend Eidolon": "Your Eidolon looks like a devil, demon, or yugoloth. **Changes.** Its type is Fiend. Strength 16 (+3), Dexterity 13 (+1), Constitution 14 (+2). It is proficient in Deception and Sleight of Hand and resists Fire and Poison damage. **Searing Pain (Bonus Action, cost 0 AP).** One creature that you or the Eidolon damaged this turn takes 1d4 Fire damage plus half your Summoner level (round up).",
  "Honorary Fiend": "You learn Infernal or Abyssal, your choice. When you fail a Charisma check with a skill, you can reroll it and must use the new roll. Once this turns a failure into a success, you cannot use it again until you finish a Short or Long Rest.",
  "Hellish Ferocity": "Once per turn, when you damage a creature with a spell, your Eidolon gains 1 AP.",
  "Protection of the Lower Planes": "**Damage Resilience.** The Eidolon's Resistance to Fire and Poison becomes Immunity, and you gain Resistance to both. **Condition Resilience.** The Eidolon is Immune to Frightened, and you have Advantage on saves to avoid or end Charmed and Frightened. **Wrath of the Lower Planes.** Searing Pain brands its target until the start of your next turn. If a branded creature damages you or your Eidolon, the Eidolon can use Searing Pain on it as a Reaction. That target then has Disadvantage on later attacks against either of you until the brand ends. Reaction uses equal your Charisma modifier (minimum 1). A Long Rest restores all.",
  "Dark Versatility": "Your Eidolon gains two Evolutions of your choice that it qualifies for. After a Long Rest you can swap them. They do not count against your Evolutions known and do not satisfy prerequisites of other Evolutions."},
 "lu": [{"feature": "Honorary Fiend", "lvl": 3, "max": 1, "reset": "short", "tag": "Reroll"},
        {"feature": "Protection of the Lower Planes", "n": "Wrath of the Lower Planes", "lvl": 10, "max": "mod:CHA", "reset": "long", "tag": "Reaction"}],
 "acts": {"Protection of the Lower Planes": "reaction"},
 "fx": [[10, "Protection of the Lower Planes", {"res": ["Fire", "Poison"]}],
        [3, "Honorary Fiend", {"notes": [["Note", "Learn Infernal or Abyssal"]]}]]},

"Bond of the Symbiote": {"spab": "CHA",
 "f": {
  "Symbiote Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: Arms of Hadar, Jump. Level 5: Alter Self, Enlarge/Reduce. Level 7: Summon Ooze. Level 9: Haste, Hunger of Hadar. Level 13: Evard's Black Tentacles. Level 17: Hold Monster, Wall of Stone.",
  "Symbiote Eidolon": "Your Eidolon is an amorphous blob of living liquid. **Changes.** Its type is Ooze. Strength 13 (+1), Dexterity 14 (+2), Constitution 16 (+3). It is proficient in Intimidation and Survival. **Enwrap (Bonus Action, cost 1 AP).** A creature it just hit with a melee attack makes a Strength save against your spell save DC. On a failure it is Grappled by the Eidolon (escape DC equals your spell save DC). The Eidolon can hold only one creature this way.",
  "Merge Bodies": "While your Eidolon is within 5 feet of you or not manifested, you can use your Manifest Eidolon action to merge it with your body. If it was manifested, it vanishes into you. While merged you gain its skill proficiencies and its Resistances and Immunities, you can use its actions, and you gain its Evolutions. It is not considered manifested, and it cannot act or be targeted. You gain Temporary Hit Points equal to three times your Summoner level, which end when you un-merge. When you make a D20 Test with Strength, you can use your Charisma modifier instead. The AP cost of its actions drops by 1, and you gain 1 AP at the start of each of your turns. You stay merged until it dissipates or you are Unconscious. You can un-merge early as a Bonus Action, and the Eidolon appears within 5 feet of you with your remaining AP. You can use this twice. A Short Rest restores one use and a Long Rest restores all.",
  "Symbiotic Synergy": "When you use your action to cast a Summoner spell while merged with your Eidolon, you can make one Conjured Strike attack as part of that action.",
  "Empowered Wrap": "When a creature fails its save against Enwrap, the Eidolon can choose one effect. **Sap Life.** The target takes 2d6 plus your Charisma modifier Necrotic damage and you regain Hit Points equal to the damage dealt. **Restrict.** The target has the Restrained condition while Grappled by the Eidolon. Uses equal your Charisma modifier (minimum 1). A Long Rest restores all.",
  "Perfect Symbiosis": "Merge Bodies no longer costs a use, and you do not gain its Temporary Hit Points when you use it this way. While merged, the Eidolon can use its own action, Bonus Action, and Reaction from your space, with tendrils bursting from your body. For Enwrap, each of you can hold one Grappled creature."},
 "lu": [{"feature": "Merge Bodies", "lvl": 3, "max": 2, "reset": "long", "tag": "Short Rest restores 1"},
        {"feature": "Empowered Wrap", "lvl": 10, "max": "mod:CHA", "reset": "long", "tag": "Sap Life or Restrict"}],
 "acts": {"Merge Bodies": "action"}},

"Bond of the Grave Caller": {"spab": "CHA",
 "f": {
  "Undead Spells": "At the Summoner levels in the table you always have these spells prepared. Level 3: False Life, Inflict Wounds. Level 5: Darkness, Ray of Enfeeblement, Summon Undead. Level 9: Animate Dead. Level 13: Blight, Death Ward. Level 17: Contagion, Dominate Person.",
  "Undead Eidolon": "Your Eidolon is a ghostly apparition or a corpse. **Changes.** Its type is Undead. Strength 14 (+2), Dexterity 13 (+1), Constitution 16 (+3). It is proficient in Intimidation and Religion, immune to Poison damage and the Poisoned condition, and resists Necrotic damage. **Undead Vessel.** Choose Corpse or Spirit when you pick this subclass. Corpse gets Undead Fortitude (Reaction): when damage other than Radiant drops it to 0 Hit Points, it makes a Constitution save against DC 10 or half the damage taken, whichever is higher, and on a success it drops to 1 Hit Point instead. Spirit gets Partially Incorporeal (Reaction): when it takes damage other than Radiant, it halves that damage. Uses equal your Charisma modifier (minimum 1). A Short Rest restores one use and a Long Rest restores all.",
  "Necromancy Expert": "Conjuration Expert also covers Necromancy spells. Wizard Necromancy spells are added to your Summoner spell list.",
  "Life Drain": "Your Eidolon gains the Bonus Action Life Drain (cost 1 AP). One creature it just damaged makes a Constitution save against your spell save DC. On a failure it takes 1d6 plus half your Summoner level (round up) Necrotic damage, half on a success. You or the Eidolon gains Temporary Hit Points equal to the damage dealt.",
  "Soul of Death": "You have Resistance to Poison and Necrotic damage and Advantage on saves to avoid or end the Poisoned condition. You can use your Eidolon's Undead Fortitude or Partially Incorporeal Reaction yourself, spending one of its uses.",
  "Ultimate Manifestation": "The benefit depends on the Undead Vessel. **Corpse.** A creature that fails its save against Life Drain is Poisoned for 1 minute and repeats the save at the end of each of its turns, ending it on a success. If it dies while Poisoned this way, it rises as a Zombie under your control. Use the Zombie stat block with your spell attack modifier for attacks and your Charisma modifier added to damage, at its former size. It acts right after your turn and dies after 1 hour or when you raise another. **Spirit.** The Eidolon becomes incorporeal. It can move through creatures, objects, and structures, but takes 1d10 Force damage if it ends its turn inside solid matter. This damage cannot be reduced."},
 "lu": [{"feature": "Undead Eidolon", "n": "Undead Vessel Reaction", "lvl": 3, "max": "mod:CHA", "reset": "long", "tag": "Short Rest restores 1"}],
 "acts": {},
 "fx": [[10, "Soul of Death", {"res": ["Poison", "Necrotic"]}]]},
}
